INSERT INTO public_question_repository (custom_id,course_tags,subject,chapter,topic,difficulty,is_pyq,pyq_year,text,option_a,option_b,option_c,option_d,correct_answer,explanation,image_path,marks,created_at) VALUES
('12-PHY-WV-0001','TS-Inter-2,MPC,JEE','Physics','Waves','Transverse','Easy',0,NULL,'In transverse waves, particle vibration is','Perpendicular to wave direction','Parallel to wave direction','Random','Circular','A','Example: light waves, string waves.',NULL,1,NOW()),
('12-PHY-WV-0002','TS-Inter-2,MPC,JEE','Physics','Waves','Longitudinal','Easy',0,NULL,'In longitudinal waves, particle vibration is','Parallel to wave direction','Perpendicular','Circular','No vibration','A','Example: sound waves, compressions and rarefactions.',NULL,1,NOW()),
('12-PHY-WV-0003','TS-Inter-2,MPC,JEE','Physics','Waves','Speed','Medium',0,NULL,'Speed of sound in air at 0°C is approximately','332 m/s','300 m/s','100 m/s','500 m/s','A','Increases with temperature.',NULL,1,NOW()),
('12-PHY-WV-0004','TS-Inter-2,MPC,JEE','Physics','Waves','v=fλ','Easy',0,NULL,'Relation between speed v, frequency f and wavelength λ is','v = fλ','v = f/λ','v = λ/f','v = f+λ','A','Fundamental wave equation.',NULL,1,NOW()),
('12-PHY-WV-0005','TS-Inter-2,MPC,JEE','Physics','Waves','Standing','Medium',1,2019,'Standing waves are formed by superposition of two waves traveling in','Opposite directions with same frequency','Same direction','Random directions','Perpendicular directions','A','Creates nodes and antinodes.',NULL,1,NOW()),
('12-PHY-WV-0006','TS-Inter-2,MPC,JEE','Physics','Waves','Node','Easy',0,NULL,'At a node in a standing wave, amplitude is','Zero (minimum)','Maximum','Half','Variable','A','Destructive interference at nodes.',NULL,1,NOW()),
('12-PHY-WV-0007','TS-Inter-2,MPC,JEE','Physics','Waves','Antinode','Easy',0,NULL,'At an antinode in a standing wave, amplitude is','Maximum','Zero','Half','Minimum','A','Constructive interference at antinodes.',NULL,1,NOW()),
('12-PHY-WV-0008','TS-Inter-2,MPC,JEE','Physics','Waves','String Fund','Medium',0,NULL,'Fundamental frequency of vibrating string of length L is','v/(2L)','v/L','2v/L','v/(4L)','A','First harmonic: λ=2L, f=v/2L.',NULL,1,NOW()),
('12-PHY-WV-0009','TS-Inter-2,MPC,JEE','Physics','Waves','Harmonics','Medium',0,NULL,'Frequency of nth harmonic in a string fixed at both ends is','nv/(2L)','v/(nL)','(2n−1)v/(4L)','nv/L','A','All harmonics present: f,2f,3f,...',NULL,1,NOW()),
('12-PHY-WV-0010','TS-Inter-2,MPC,JEE','Physics','Waves','Open Pipe','Medium',1,2020,'Frequencies in open organ pipe are','All harmonics: f,2f,3f,...','Odd harmonics only','Even harmonics only','No harmonics','A','Both ends are antinodes.',NULL,1,NOW()),
('12-PHY-WV-0011','TS-Inter-2,MPC,JEE','Physics','Waves','Closed Pipe','Medium',0,NULL,'Frequencies in closed organ pipe are','Odd harmonics only: f,3f,5f,...','All harmonics','Even only','No pattern','A','One end node, other antinode.',NULL,1,NOW()),
('12-PHY-WV-0012','TS-Inter-2,MPC,JEE','Physics','Waves','Beats','Medium',0,NULL,'Beat frequency when two tuning forks of f₁ and f₂ sound together is','|f₁−f₂|','f₁+f₂','f₁×f₂','(f₁+f₂)/2','A','Number of beats per second.',NULL,1,NOW()),
('12-PHY-WV-0013','TS-Inter-2,MPC,JEE','Physics','Waves','Doppler','Hard',0,NULL,'When source moves toward stationary observer, apparent frequency','Increases','Decreases','Stays same','Becomes zero','A','Wavelength compressed, higher frequency.',NULL,1,NOW()),
('12-PHY-WV-0014','TS-Inter-2,MPC,JEE','Physics','Waves','Doppler Eqn','Hard',0,NULL,'Doppler formula for sound: f''=f(v±v₀)/(v∓vₛ). When source approaches observer','Use f(v+v₀)/(v−vₛ) for both moving toward','f(v−v₀)/(v+vₛ)','f','fv/vₛ','A','Sign convention: toward = numerator +, denominator −.',NULL,1,NOW()),
('12-PHY-WV-0015','TS-Inter-2,MPC,JEE','Physics','Waves','Resonance','Medium',1,2021,'Resonance occurs when','Driving frequency matches natural frequency','Frequencies differ','Amplitude is zero','No vibration','A','Maximum energy transfer at resonance.',NULL,1,NOW()),
('12-PHY-WV-0016','TS-Inter-2,MPC,JEE','Physics','Waves','v in String','Medium',0,NULL,'Speed of wave in string v = ','√(T/μ) where T=tension, μ=linear density','T/μ','μ/T','T×μ','A','Depends on tension and mass per unit length.',NULL,1,NOW()),
('12-PHY-WV-0017','TS-Inter-2,MPC,JEE','Physics','Waves','Sound Medium','Easy',0,NULL,'Sound cannot travel through','Vacuum','Air','Water','Steel','A','Sound needs material medium.',NULL,1,NOW()),
('12-PHY-WV-0018','TS-Inter-2,MPC,JEE','Physics','Waves','Intensity','Medium',0,NULL,'Intensity of sound is proportional to','Square of amplitude','Amplitude','Cube of amplitude','1/amplitude','A','I ∝ A².',NULL,1,NOW()),
('12-PHY-WV-0019','TS-Inter-2,MPC,JEE','Physics','Waves','dB','Medium',0,NULL,'Sound intensity level in decibels: β =','10 log₁₀(I/I₀)','I/I₀','ln(I/I₀)','I×I₀','A','I₀=10⁻¹² W/m² (threshold of hearing).',NULL,1,NOW()),
('12-PHY-WV-0020','TS-Inter-2,MPC,JEE','Physics','Waves','Superposition','Easy',0,NULL,'Principle of superposition states resultant displacement is','Sum of individual displacements','Product','Difference','Average','A','y = y₁+y₂+y₃+...',NULL,1,NOW()),
('12-PHY-WV-0021','TS-Inter-2,MPC,JEE','Physics','Waves','String Law','Medium',0,NULL,'For vibrating string, frequency is inversely proportional to','Length (for constant T and μ)','Tension','Mass','None','A','f=v/(2L), f∝1/L.',NULL,1,NOW()),
('12-PHY-WV-0022','TS-Inter-2,MPC,JEE','Physics','Waves','Sonometer','Medium',0,NULL,'Sonometer is used to verify','Laws of vibrating strings','Doppler effect','Beats','Resonance only','A','Adjustable length, tension for frequency studies.',NULL,1,NOW()),
('12-PHY-WV-0023','TS-Inter-2,MPC,JEE','Physics','Waves','End Correction','Hard',0,NULL,'End correction for open pipe is approximately','0.6d at each end (d=diameter)','0','d','2d','A','Antinode forms slightly outside the pipe.',NULL,1,NOW()),
('12-PHY-WV-0024','TS-Inter-2,MPC,JEE','Physics','Waves','Velocity Temp','Medium',0,NULL,'Speed of sound in air varies with temperature as v ∝','√T (absolute temperature)','T','T²','1/T','A','v = v₀√(T/273).',NULL,1,NOW()),
('12-PHY-WV-0025','TS-Inter-2,MPC,JEE','Physics','Waves','Velocity Gas','Hard',1,2020,'Speed of sound in gas: v =','√(γP/ρ) (Newton-Laplace)','P/ρ','√(P/ρ)','γP/ρ','A','γ = ratio of specific heats (adiabatic process).',NULL,1,NOW()),
('12-PHY-WV-0026','TS-Inter-2,MPC,JEE','Physics','Waves','Progressive','Easy',0,NULL,'A progressive wave equation is y =','A sin(ωt−kx)','A sin(ωt)cos(kx)','A cos(kx)','Constant','A','Traveling wave: amplitude, angular frequency, wave number.',NULL,1,NOW()),
('12-PHY-WV-0027','TS-Inter-2,MPC,JEE','Physics','Waves','k','Medium',0,NULL,'Wave number k = ','2π/λ','1/λ','λ/2π','2πλ','A','Spatial frequency of the wave.',NULL,1,NOW()),
('12-PHY-WV-0028','TS-Inter-2,MPC,JEE','Physics','Waves','ω','Medium',0,NULL,'Angular frequency ω = ','2πf','f/2π','πf','f','A','ω = 2π/T = 2πf.',NULL,1,NOW()),
('12-PHY-WV-0029','TS-Inter-2,MPC,JEE','Physics','Waves','Melde','Medium',1,2021,'In Melde''s experiment with transverse arrangement, frequency f and number of loops p are related as','f ∝ p','f ∝ 1/p','f = constant','f ∝ p²','A','More loops at higher frequency.',NULL,1,NOW()),
('12-PHY-WV-0030','TS-Inter-2,MPC,JEE','Physics','Waves','Energy','Hard',0,NULL,'Energy in a wave is proportional to','f² and A² (frequency² × amplitude²)','f only','A only','1/(fA)','A','E ∝ A²f².',NULL,1,NOW());
